"use client";

import { CustomEase } from "gsap/CustomEase";
import { gsap } from "gsap";
import { cubicBezierToGsap } from "./export-motion-profile";
import {
  GSAP_EASE_NAMES,
  NATIVE_GSAP_EASE_NAMES,
} from "./gsap-ease-names";
import { TWEEN_INTENTS, type MotionProfileData } from "./profiles/types";

let registeredSignature: string | null = null;
let pluginRegistered = false;

const customEasePlugin = CustomEase;

function profileEaseSignature(profile: MotionProfileData): string {
  return JSON.stringify(profile.easing);
}

export function registerMotionEases(profile: MotionProfileData) {
  if (typeof window === "undefined") {
    return;
  }

  if (!pluginRegistered) {
    gsap.registerPlugin(customEasePlugin);
    pluginRegistered = true;
  }

  const signature = profileEaseSignature(profile);
  if (registeredSignature === signature) {
    return;
  }

  for (const intent of TWEEN_INTENTS) {
    const name = GSAP_EASE_NAMES[intent];
    if (NATIVE_GSAP_EASE_NAMES.has(name)) {
      throw new Error(
        `Refusing to register ${name}. Semantic GSAP eases must not overwrite native names.`,
      );
    }
    customEasePlugin.create(name, cubicBezierToGsap(profile.easing[intent]));
  }

  registeredSignature = signature;
}

export function getMotionEaseRegistrationSignature() {
  return registeredSignature;
}

export function resetMotionEaseRegistration() {
  registeredSignature = null;
  pluginRegistered = false;
}

export { CustomEase, GSAP_EASE_NAMES, NATIVE_GSAP_EASE_NAMES };

import { serializeMotionProfile } from "./profiles/create-motion-profile";
import {
  DURATION_TOKENS,
  STAGGER_TOKENS,
  TWEEN_INTENTS,
  type CubicBezier,
  type MotionProfileData,
  type TweenIntent,
} from "./profiles/types";
import { GSAP_EASE_NAMES } from "./gsap-ease-names";

export function cubicBezierToCss(bezier: CubicBezier): string {
  return `cubic-bezier(${bezier[0]}, ${bezier[1]}, ${bezier[2]}, ${bezier[3]})`;
}

export function cubicBezierToGsap(bezier: CubicBezier): string {
  return `${bezier[0]},${bezier[1]},${bezier[2]},${bezier[3]}`;
}

export function motionProfileToCss(profile: MotionProfileData): string {
  const data = serializeMotionProfile(profile);
  const easeLines = TWEEN_INTENTS.map(
    (intent) => `  --ease-${intent}: ${cubicBezierToCss(data.easing[intent])};`,
  );
  const durationLines = DURATION_TOKENS.map(
    (token) => `  --duration-${token}: ${String(data.duration[token])}s;`,
  );
  const staggerLines = STAGGER_TOKENS.map(
    (token) => `  --stagger-${token}: ${String(data.stagger[token])}s;`,
  );

  return [":root {", ...easeLines, ...durationLines, ...staggerLines, "}"].join(
    "\n",
  );
}

export function motionProfileToMotionTs(profile: MotionProfileData): string {
  const data = serializeMotionProfile(profile);
  return `import { createMotionProfile } from "@cds/motion";

export const projectMotionProfile = createMotionProfile(${JSON.stringify(data, null, 2)});
`;
}

export function motionProfileToGsapRegistration(
  profile: MotionProfileData,
): Record<(typeof GSAP_EASE_NAMES)[TweenIntent], string> {
  const data = serializeMotionProfile(profile);
  return {
    [GSAP_EASE_NAMES.enter]: cubicBezierToGsap(data.easing.enter),
    [GSAP_EASE_NAMES.settle]: cubicBezierToGsap(data.easing.settle),
    [GSAP_EASE_NAMES.move]: cubicBezierToGsap(data.easing.move),
    [GSAP_EASE_NAMES.exit]: cubicBezierToGsap(data.easing.exit),
    [GSAP_EASE_NAMES.linear]: cubicBezierToGsap(data.easing.linear),
  };
}

export function motionProfileToJson(profile: MotionProfileData): string {
  return `${JSON.stringify(serializeMotionProfile(profile), null, 2)}\n`;
}

"use client";

import { gsap } from "gsap";
import { CustomEase } from "gsap/CustomEase";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useGSAP } from "@gsap/react";

let registered = false;
const plugins = [ScrollTrigger, useGSAP, CustomEase];

export function registerGsap() {
  if (registered || typeof window === "undefined") {
    return;
  }
  gsap.registerPlugin(...plugins);
  registered = true;
}

export function reducedMotionMatchMedia() {
  return gsap.matchMedia();
}

export { CustomEase, gsap, ScrollTrigger, useGSAP };

"use client";

import "lenis/dist/lenis.css";
import { ReactLenis, type LenisRef } from "lenis/react";
import { useReducedMotion } from "motion/react";
import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { FINE_POINTER_QUERY } from "./motion-policy";
import {
  resolveSmoothScrollMode,
  shouldEnableLenis,
  shouldPreventLenis,
  SMOOTH_SCROLL_DEFAULTS,
  type SmoothScrollMode,
} from "./smooth-scroll-options";
import { attachGsapLenisSync } from "./smooth-scroll-sync";
import {
  SmoothScrollContext,
  type SmoothScrollApi,
} from "./use-smooth-scroll";

export type SmoothScrollProviderProps = {
  children: ReactNode;
  lerp?: number;
};

export function SmoothScrollProvider({
  children,
  lerp = SMOOTH_SCROLL_DEFAULTS.lerp,
}: SmoothScrollProviderProps) {
  const reduce = useReducedMotion();
  const [finePointer, setFinePointer] = useState(false);
  const lenisRef = useRef<LenisRef>(null);
  const mode: SmoothScrollMode = resolveSmoothScrollMode({
    reduce,
    finePointer,
  });
  const enableLenis = shouldEnableLenis(mode);

  useEffect(() => {
    const media = window.matchMedia(FINE_POINTER_QUERY);
    const update = () => {
      setFinePointer(media.matches);
    };
    update();
    media.addEventListener("change", update);
    return () => {
      media.removeEventListener("change", update);
    };
  }, []);

  useEffect(() => {
    document.documentElement.dataset.smoothScrollMode = mode;
    return () => {
      delete document.documentElement.dataset.smoothScrollMode;
    };
  }, [mode]);

  useEffect(() => {
    if (!enableLenis) {
      return;
    }
    return attachGsapLenisSync(() => lenisRef.current?.lenis ?? null);
  }, [enableLenis]);

  const api = useMemo<SmoothScrollApi>(() => {
    const lenis = enableLenis ? (lenisRef.current?.lenis ?? null) : null;
    return {
      lenis,
      mode,
      scrollTo: (target, options) => {
        const instance = lenisRef.current?.lenis;
        if (instance) {
          instance.scrollTo(target, options);
          return;
        }
        if (typeof window === "undefined") {
          return;
        }
        const behavior = options?.immediate ? "auto" : "smooth";
        if (typeof target === "number") {
          window.scrollTo({ top: target, behavior });
          return;
        }
        if (typeof target === "string") {
          if (target === "top" || target === "start") {
            window.scrollTo({ top: 0, behavior });
            return;
          }
          document.querySelector(target)?.scrollIntoView({
            behavior,
            block: "start",
          });
          return;
        }
        target.scrollIntoView({ behavior, block: "start" });
      },
      start: () => {
        lenisRef.current?.lenis?.start();
      },
      stop: () => {
        lenisRef.current?.lenis?.stop();
      },
      resize: () => {
        lenisRef.current?.lenis?.resize();
      },
    };
  }, [enableLenis, mode]);

  if (!enableLenis) {
    return (
      <SmoothScrollContext.Provider value={{ ...api, lenis: null, mode }}>
        {children}
      </SmoothScrollContext.Provider>
    );
  }

  return (
    <SmoothScrollContext.Provider value={api}>
      <ReactLenis
        root
        ref={lenisRef}
        options={{
          autoRaf: SMOOTH_SCROLL_DEFAULTS.autoRaf,
          lerp,
          anchors: SMOOTH_SCROLL_DEFAULTS.anchors,
          stopInertiaOnNavigate: SMOOTH_SCROLL_DEFAULTS.stopInertiaOnNavigate,
          syncTouch: SMOOTH_SCROLL_DEFAULTS.syncTouch,
          smoothWheel: SMOOTH_SCROLL_DEFAULTS.smoothWheel,
          respectReducedMotion: SMOOTH_SCROLL_DEFAULTS.respectReducedMotion,
          prevent: shouldPreventLenis,
        }}
      >
        {children}
      </ReactLenis>
    </SmoothScrollContext.Provider>
  );
}

"use client";

import type Lenis from "lenis";
import { createContext, useContext } from "react";
import { FINE_POINTER_QUERY } from "./motion-policy";
import { getReducedMotionSnapshot } from "./reduced-motion";
import {
  resolveSmoothScrollMode,
  type SmoothScrollMode,
} from "./smooth-scroll-options";

export type SmoothScrollToTarget = number | string | HTMLElement;

export type SmoothScrollToOptions = {
  immediate?: boolean;
  offset?: number;
  lock?: boolean;
};

export type SmoothScrollApi = {
  lenis: Lenis | null;
  mode: SmoothScrollMode;
  scrollTo: (target: SmoothScrollToTarget, options?: SmoothScrollToOptions) => void;
  start: () => void;
  stop: () => void;
  resize: () => void;
};

export const SmoothScrollContext = createContext<SmoothScrollApi | null>(null);

function nativeScrollTo(
  target: SmoothScrollToTarget,
  options?: SmoothScrollToOptions,
) {
  if (typeof window === "undefined") {
    return;
  }
  const behavior = options?.immediate ? "auto" : "smooth";
  if (typeof target === "number") {
    window.scrollTo({ top: target, behavior });
    return;
  }
  if (typeof target === "string") {
    if (target === "top" || target === "start") {
      window.scrollTo({ top: 0, behavior });
      return;
    }
    const node = document.querySelector(target);
    node?.scrollIntoView({ behavior, block: "start" });
    return;
  }
  target.scrollIntoView({ behavior, block: "start" });
}

export const nativeSmoothScrollApi: SmoothScrollApi = {
  lenis: null,
  mode: "reduced-motion",
  scrollTo: nativeScrollTo,
  start: () => undefined,
  stop: () => undefined,
  resize: () => undefined,
};

/**
 * Control API for the app-level SmoothScrollProvider.
 * Outside the provider this returns native window scrolling (lenis is null).
 */
export function useSmoothScroll(): SmoothScrollApi {
  const value = useContext(SmoothScrollContext);
  if (value) {
    return value;
  }
  const reduce = getReducedMotionSnapshot();
  const finePointer =
    typeof window !== "undefined" &&
    window.matchMedia(FINE_POINTER_QUERY).matches;
  return {
    ...nativeSmoothScrollApi,
    mode: resolveSmoothScrollMode({ reduce, finePointer }),
  };
}

import { FINE_POINTER_QUERY } from "./motion-policy";

export type SmoothScrollMode = "smooth" | "native-touch" | "reduced-motion";

export type SmoothScrollOptions = {
  lerp: number;
  anchors: boolean;
  stopInertiaOnNavigate: boolean;
  syncTouch: boolean;
  smoothWheel: boolean;
  autoRaf: boolean;
  respectReducedMotion: boolean;
};

export const SMOOTH_SCROLL_DEFAULTS: SmoothScrollOptions = {
  lerp: 0.1,
  anchors: true,
  stopInertiaOnNavigate: true,
  syncTouch: false,
  smoothWheel: true,
  autoRaf: false,
  respectReducedMotion: true,
};

export const LENIS_PREVENT_SELECTOR =
  "[data-lenis-prevent], [data-radix-dialog-content], [role='dialog']";

export function resolveSmoothScrollMode(options: {
  reduce: boolean | null | undefined;
  finePointer: boolean;
}): SmoothScrollMode {
  if (options.reduce) {
    return "reduced-motion";
  }
  if (!options.finePointer) {
    return "native-touch";
  }
  return "smooth";
}

export function shouldEnableLenis(mode: SmoothScrollMode): boolean {
  return mode === "smooth";
}

export function shouldPreventLenis(node: HTMLElement): boolean {
  return Boolean(node.closest(LENIS_PREVENT_SELECTOR));
}

export { FINE_POINTER_QUERY };

import type Lenis from "lenis";
import { gsap, registerGsap, ScrollTrigger } from "./gsap";

type SyncRecord = {
  ticker: (time: number) => void;
  onScroll: () => void;
  boundLenis: Lenis | null;
};

let active: SyncRecord | null = null;

export function getGsapLenisSyncCount(): number {
  return active ? 1 : 0;
}

export function attachGsapLenisSync(
  getLenis: () => Lenis | null | undefined,
): () => void {
  registerGsap();

  if (active) {
    detach(active);
  }

  const onScroll = () => {
    ScrollTrigger.update();
  };

  const record: SyncRecord = {
    ticker: (time: number) => {
      const lenis = getLenis();
      if (!lenis) {
        return;
      }
      if (record.boundLenis !== lenis) {
        record.boundLenis?.off("scroll", onScroll);
        lenis.on("scroll", onScroll);
        record.boundLenis = lenis;
      }
      lenis.raf(time * 1000);
    },
    onScroll,
    boundLenis: null,
  };

  gsap.ticker.add(record.ticker);
  gsap.ticker.lagSmoothing(0);
  active = record;

  return () => {
    detach(record);
  };
}

function detach(record: SyncRecord) {
  if (active !== record) {
    return;
  }
  gsap.ticker.remove(record.ticker);
  record.boundLenis?.off("scroll", record.onScroll);
  gsap.ticker.lagSmoothing(500, 33);
  active = null;
}

export const FINE_POINTER_QUERY = "(pointer: fine) and (hover: hover)";

export function shouldAnimateMotion(
  reduce: boolean | null | undefined,
): boolean {
  return !reduce;
}

export function shouldEnableParallax(options: {
  reduce: boolean | null | undefined;
  viewportWidth: number | null;
  disableBelow?: number;
}): boolean {
  if (!shouldAnimateMotion(options.reduce)) {
    return false;
  }
  if (
    options.disableBelow != null &&
    options.viewportWidth != null &&
    options.viewportWidth < options.disableBelow
  ) {
    return false;
  }
  return true;
}

export function shouldEnableMagnetic(options: {
  reduce: boolean | null | undefined;
  finePointer: boolean;
  pointerType?: string;
}): boolean {
  if (!shouldAnimateMotion(options.reduce)) {
    return false;
  }
  if (!options.finePointer) {
    return false;
  }
  if (
    options.pointerType &&
    options.pointerType !== "mouse" &&
    options.pointerType !== "pen"
  ) {
    return false;
  }
  return true;
}

export function shouldEnablePointerAccent(options: {
  enabled: boolean;
  reduce: boolean | null | undefined;
  finePointer: boolean;
  pointerType?: string;
}): boolean {
  if (!options.enabled) {
    return false;
  }
  return shouldEnableMagnetic({
    reduce: options.reduce,
    finePointer: options.finePointer,
    pointerType: options.pointerType,
  });
}

"use client";

import { useReducedMotion } from "motion/react";

export const reducedMotionQuery = "(prefers-reduced-motion: reduce)";

export function getReducedMotionSnapshot(): boolean {
  if (typeof window === "undefined") {
    return false;
  }
  return window.matchMedia(reducedMotionQuery).matches;
}

export function usePrefersReducedMotion(): boolean {
  return Boolean(useReducedMotion());
}

export const reducedMotionCss = {
  query: reducedMotionQuery,
  disableTransitions: `
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
`,
};

import type { CubicBezier, DurationToken, MotionProfileData, TweenIntent } from "./profiles/types";

export type ResolveTweenOptions = {
  intent?: TweenIntent;
  ease?: CubicBezier;
  duration?: number;
  durationToken?: DurationToken;
};

export function toMotionEase(
  ease: CubicBezier,
): [number, number, number, number] {
  return [ease[0], ease[1], ease[2], ease[3]];
}

export function resolveTween(
  profile: MotionProfileData,
  options: ResolveTweenOptions = {},
): { duration: number; ease: CubicBezier } {
  const intent = options.intent ?? "enter";
  return {
    duration:
      options.duration ??
      profile.duration[options.durationToken ?? "base"],
    ease: options.ease ?? profile.easing[intent],
  };
}

"use client";

import { createContext, useContext } from "react";
import { houseMotionProfile } from "./profiles/create-motion-profile";
import type { MotionProfile } from "./profiles/types";

export const MotionProfileContext =
  createContext<MotionProfile>(houseMotionProfile);

export function useMotionProfile(): MotionProfile {
  return useContext(MotionProfileContext);
}

export const TWEEN_INTENTS = [
  "enter",
  "settle",
  "move",
  "exit",
  "linear",
] as const;

export const SPRING_INTENTS = ["pop"] as const;

export const DURATION_TOKENS = ["instant", "fast", "base", "slow"] as const;

export const STAGGER_TOKENS = ["tight", "normal", "expressive"] as const;

export type TweenIntent = (typeof TWEEN_INTENTS)[number];

export type SpringIntent = (typeof SPRING_INTENTS)[number];

export type DurationToken = (typeof DURATION_TOKENS)[number];

export type StaggerToken = (typeof STAGGER_TOKENS)[number];

export type CubicBezier = readonly [number, number, number, number];

export type SpringConfig = {
  type: "spring";
  stiffness: number;
  damping: number;
  mass: number;
  velocity?: number;
};

export type MotionProfileData = {
  easing: Record<TweenIntent, CubicBezier>;
  spring: Record<SpringIntent, SpringConfig>;
  duration: Record<DurationToken, number>;
  stagger: Record<StaggerToken, number>;
};

export type MotionProfileOverride = {
  easing?: Partial<Record<TweenIntent, CubicBezier>>;
  spring?: Partial<Record<SpringIntent, Partial<SpringConfig>>>;
  duration?: Partial<Record<DurationToken, number>>;
  stagger?: Partial<Record<StaggerToken, number>>;
};

export type MotionProfile = MotionProfileData & {
  ease: (intent: TweenIntent) => CubicBezier;
  springOf: (intent?: SpringIntent) => SpringConfig;
  durationOf: (token: DurationToken) => number;
  staggerOf: (token: StaggerToken) => number;
};

export class MotionProfileError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MotionProfileError";
  }
}

import { HOUSE_MOTION_PROFILE } from "./house";
import {
  DURATION_TOKENS,
  MotionProfileError,
  SPRING_INTENTS,
  STAGGER_TOKENS,
  TWEEN_INTENTS,
  type CubicBezier,
  type MotionProfile,
  type MotionProfileData,
  type MotionProfileOverride,
  type SpringConfig,
  type TweenIntent,
} from "./types";

function isFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

export function assertCubicBezier(
  value: unknown,
  path: string,
): asserts value is CubicBezier {
  if (!Array.isArray(value) || value.length !== 4) {
    throw new MotionProfileError(
      `${path} must be a cubic Bézier of four numbers [x1, y1, x2, y2].`,
    );
  }

  const [x1, y1, x2, y2] = value;
  if (
    !isFiniteNumber(x1) ||
    !isFiniteNumber(y1) ||
    !isFiniteNumber(x2) ||
    !isFiniteNumber(y2)
  ) {
    throw new MotionProfileError(`${path} Bézier values must be finite numbers.`);
  }

  if (x1 < 0 || x1 > 1 || x2 < 0 || x2 > 1) {
    throw new MotionProfileError(
      `${path} X control points must stay between 0 and 1. Received x1=${String(x1)}, x2=${String(x2)}.`,
    );
  }
}

function assertPositive(value: unknown, path: string) {
  if (!isFiniteNumber(value) || value <= 0) {
    throw new MotionProfileError(`${path} must be a finite number greater than 0.`);
  }
}

function assertSpring(value: SpringConfig, path: string) {
  if (value.type !== "spring") {
    throw new MotionProfileError(`${path}.type must be "spring".`);
  }
  assertPositive(value.stiffness, `${path}.stiffness`);
  assertPositive(value.damping, `${path}.damping`);
  assertPositive(value.mass, `${path}.mass`);
  if (value.velocity !== undefined && !isFiniteNumber(value.velocity)) {
    throw new MotionProfileError(`${path}.velocity must be a finite number when set.`);
  }
}

export function validateMotionProfileData(
  data: MotionProfileData,
): MotionProfileData {
  for (const intent of TWEEN_INTENTS) {
    assertCubicBezier(data.easing[intent], `easing.${intent}`);
  }

  for (const intent of SPRING_INTENTS) {
    assertSpring(data.spring[intent], `spring.${intent}`);
  }

  for (const token of DURATION_TOKENS) {
    assertPositive(data.duration[token], `duration.${token}`);
  }

  for (const token of STAGGER_TOKENS) {
    assertPositive(data.stagger[token], `stagger.${token}`);
  }

  return data;
}

function copyBezier(value: CubicBezier): CubicBezier {
  return [value[0], value[1], value[2], value[3]];
}

function mergeProfile(
  base: MotionProfileData,
  overrides: MotionProfileOverride,
): MotionProfileData {
  return {
    easing: {
      enter: copyBezier(overrides.easing?.enter ?? base.easing.enter),
      settle: copyBezier(overrides.easing?.settle ?? base.easing.settle),
      move: copyBezier(overrides.easing?.move ?? base.easing.move),
      exit: copyBezier(overrides.easing?.exit ?? base.easing.exit),
      linear: copyBezier(overrides.easing?.linear ?? base.easing.linear),
    },
    spring: {
      pop: {
        type: "spring",
        stiffness: overrides.spring?.pop?.stiffness ?? base.spring.pop.stiffness,
        damping: overrides.spring?.pop?.damping ?? base.spring.pop.damping,
        mass: overrides.spring?.pop?.mass ?? base.spring.pop.mass,
        velocity: overrides.spring?.pop?.velocity ?? base.spring.pop.velocity,
      },
    },
    duration: {
      instant: overrides.duration?.instant ?? base.duration.instant,
      fast: overrides.duration?.fast ?? base.duration.fast,
      base: overrides.duration?.base ?? base.duration.base,
      slow: overrides.duration?.slow ?? base.duration.slow,
    },
    stagger: {
      tight: overrides.stagger?.tight ?? base.stagger.tight,
      normal: overrides.stagger?.normal ?? base.stagger.normal,
      expressive: overrides.stagger?.expressive ?? base.stagger.expressive,
    },
  };
}

function withRuntime(data: MotionProfileData): MotionProfile {
  const profile: MotionProfile = {
    ...data,
    ease(intent: TweenIntent) {
      return profile.easing[intent];
    },
    springOf(intent = "pop") {
      return profile.spring[intent];
    },
    durationOf(token) {
      return profile.duration[token];
    },
    staggerOf(token) {
      return profile.stagger[token];
    },
  };
  return profile;
}

export function createMotionProfile(
  overrides: MotionProfileOverride = {},
  base: MotionProfileData = HOUSE_MOTION_PROFILE,
): MotionProfile {
  return withRuntime(validateMotionProfileData(mergeProfile(base, overrides)));
}

export const houseMotionProfile = createMotionProfile();

export function serializeMotionProfile(
  profile: MotionProfileData,
): MotionProfileData {
  const validated = validateMotionProfileData(mergeProfile(HOUSE_MOTION_PROFILE, profile));
  return {
    easing: {
      enter: copyBezier(validated.easing.enter),
      settle: copyBezier(validated.easing.settle),
      move: copyBezier(validated.easing.move),
      exit: copyBezier(validated.easing.exit),
      linear: copyBezier(validated.easing.linear),
    },
    spring: {
      pop: { ...validated.spring.pop },
    },
    duration: { ...validated.duration },
    stagger: { ...validated.stagger },
  };
}

